    function testFuzz_property(uint256 amount) public {
        // Keep domain wide but ensure we test meaningful cases; allow zero too
        // Call as owner (setUp deployed c from this address)
        // Call AdjustBetAmounts and then assert that betLimit equals the provided amount
        bool ok;
        try c.AdjustBetAmounts(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // If the contract call reverted that's already a violation of expected external behavior
        // but the property to check is that after a successful call, betLimit == amount.
        // We only assert the property when the call succeeded.
        if (ok) {
