            assertTrue(false);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single entry that performs the minimal sequence: attempt to change bet limit from a caller that may not be owner,
    // then assert that if the caller is not the contract owner, the bet limit did not change.
    // Inputs:
    // - callerIsOwner: whether this contract should act as owner (true) or non-owner (false)
    // - newLimit: the value to pass to AdjustBetAmounts
    function run(bool callerIsOwner, uint256 newLimit) public {
        // precondition: capture original bet limit
        uint256 before = c.currentBetLimit();

        // If the test runner intends this contract to be owner, the deployment of C must have set its owner to this contract.
        // We cannot change msg.sender here; the caller of run() is this transaction sender.
        // To simulate both cases, the rule asserts behavior conditional on whether this contract is the owner by comparing
        // address(this) against the owner-observable behavior: onlyOwner prevents non-owners from changing bet limit.

        // Call AdjustBetAmounts as this contract (msg.sender = address(this))
        c.AdjustBetAmounts(newLimit);

        uint256 after = c.currentBetLimit();

        // If this contract was not the owner, AdjustBetAmounts should not have changed the bet limit.
        // We express callerIsOwner as a declared input: when callerIsOwner == false, assert after == before.
        // When callerIsOwner == true, owner is allowed to change the limit, so we do not constrain that case.
        if (!callerIsOwner) {
            assert(after == before);
        } else {
            // If callerIsOwner is true, ensure nothing forces a contradiction: allow any outcome.
            assert(true);
        }
    }

    // Allow contract to receive ETH if needed by target contract calls
    receive() external payable {}
}

