contract InvMutTest is Test {
    C c;
    address ownerAddr;

    function setUp() public { c = new C(address(this), 0); ownerAddr = address(this); }

    // fuzzed params: a caller address and a newBetLimit value
    function testFuzz_property(address caller, uint256 newBetLimit) public {
        // keep the domain wide but avoid the zero address as a caller (still admissible though)
        vm.assume(caller != address(0));

        // record original bet limit
        uint256 before = c.currentBetLimit();

        // ensure caller has some ETH so they can call if needed (AdjustBetAmounts is non-payable but harmless)
        vm.deal(caller, 1 ether);

        bool ok;
        // try calling AdjustBetAmounts as the fuzzed caller
        vm.prank(caller);
        try c.AdjustBetAmounts(newBetLimit) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 after = c.currentBetLimit();

        // General rule: If the caller is not the owner, the reference contract must NOT allow them to change betLimit;
        // hence after == before for all non-owner callers. This property holds for the reference and is violated by the mutant
        // that removes the onlyOwner check (which allows non-owners to change betLimit for some inputs).
        if (caller != ownerAddr) {
            assertTrue(after == before);
        } else {
            // owner may change it — if owner called and the call succeeded, betLimit should equal newBetLimit
            if (ok) {
                assertTrue(after == newBetLimit);
            } else {
                // if owner's call reverted for some reason, betLimit should remain unchanged
                assertTrue(after == before);
            }
        }
    }
}

