import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    // fuzzed params: the owner caller address and the amount to set
    // We fuzz an address to act as owner (ownerAddr) and an amount to set as difficulty (amount).
    // The reference contract requires onlyOwner; in setUp() we deployed c with owner = address(this),
    // so to call AdjustDifficulty we must have the call come from address(this). To let the fuzzer
    // vary the owner address while still being able to call as that owner, we instead fuzz a uint256
    // ownerPrivateKey which we use with vm.prank to simulate arbitrary caller addresses via
    // vm.addr(ownerPrivateKey). This lets the fuzzer search for an address where the mutant differs.
    function testFuzz_property(uint256 ownerPrivateKey, uint256 amount) public {
        // bound the private key to a large range but keep it wide
        ownerPrivateKey = bound(ownerPrivateKey, 1, type(uint256).max);
        address ownerAddr = vm.addr(ownerPrivateKey);

        // Only proceed when ownerAddr equals address(this) because only the real owner (deployer)
        // can call AdjustDifficulty; the correct contract's rule must hold for every admissible input
        // where the call succeeds. We therefore fuzz over ownerPrivateKey but only call when it matches
        // the actual owner. This lets the fuzzer search for owner addresses that differ in the mutant
        // behaviour when owner==address(this) (note: the mutant uses msg.sender to set difficulty, so
        // when owner==address(this) the mutant will set difficulty to uint160(msg.sender)==uint160(address(this))).
        // To ensure the test is general, we allow any amount; the correct contract sets difficulty==amount.

        // If the fuzzed owner is not the real owner, the call would revert due to onlyOwner; skip those cases.
        vm.assume(ownerAddr == address(this));

        // Now call AdjustDifficulty as owner (address(this)) with the fuzzed amount
        // No need to vm.prank since msg.sender is already address(this) in this test context
        c.AdjustDifficulty(amount);

        // The general property: after AdjustDifficulty(amount) completes when called by the owner,
        // the contract's difficulty getter must equal the provided amount. The mutant will break this
        // for some owner addresses because it assigns difficulty = uint160(msg.sender) instead.
        assertTrue(c.currentDifficulty() == amount);
    }
}

